mapper.select:
SELECT COUNT(*)
FROM kb_grant g
WHERE g.kb_id = #{kbId}
  AND (
      (g.grantee_type = 'USER' AND g.grantee_id = #{userId})
      OR (g.grantee_type = 'ROLE' AND g.grantee_id IN (
          SELECT ur.role_id FROM sys_user_role ur WHERE ur.user_id = #{userId}
      ))
  )

SELECT COUNT(*)
FROM kb_grant g
WHERE g.kb_id = #{kbId}
  AND g.permission = 'MANAGE'
  AND (
      (g.grantee_type = 'USER' AND g.grantee_id = #{userId})
      OR (g.grantee_type = 'ROLE' AND g.grantee_id IN (
          SELECT ur.role_id FROM sys_user_role ur WHERE ur.user_id = #{userId}
      ))
  )

SELECT DISTINCT g.kb_id
FROM kb_grant g
WHERE (g.grantee_type = 'USER' AND g.grantee_id = #{userId})
   OR (g.grantee_type = 'ROLE' AND g.grantee_id IN (
       SELECT ur.role_id FROM sys_user_role ur WHERE ur.user_id = #{userId}
   ))
